    dst_p->bms_fault_weak_cell = unpack_right_shift_u8(src_p[3], 2u, 0x04u);
    dst_p->bms_fault_low_cell_voltage = unpack_right_shift_u8(src_p[3], 3u, 0x08u);
    dst_p->bms_fault_cell_open_wiring = unpack_right_shift_u8(src_p[3], 4u, 0x10u);
    dst_p->bms_fault_current_sensor = unpack_right_shift_u8(src_p[3], 5u, 0x20u);
    dst_p->bms_fault_cell_voltage_over_5_v = unpack_right_shift_u8(src_p[3], 6u, 0x40u);
    dst_p->bms_fault_cell_bank = unpack_right_shift_u8(src_p[3], 7u, 0x80u);
    dst_p->bms_fault_weak_pack = unpack_right_shift_u8(src_p[4], 0u, 0x01u);
    dst_p->bms_fault_fan_monitor = unpack_right_shift_u8(src_p[4], 1u, 0x02u);
    dst_p->bms_fault_thermistor = unpack_right_shift_u8(src_p[4], 2u, 0x04u);
    dst_p->bms_fault_can_communication = unpack_right_shift_u8(src_p[4], 3u, 0x08u);
    dst_p->bms_fault_redundant_power_supply = unpack_right_shift_u8(src_p[4], 4u, 0x10u);
    dst_p->bms_fault_high_voltage_isolation = unpack_right_shift_u8(src_p[4], 5u, 0x20u);
    dst_p->bms_fault_invld_input_sply_volt = unpack_right_shift_u8(src_p[4], 6u, 0x40u);
    dst_p->bms_fault_charge_enable_relay = unpack_right_shift_u8(src_p[4], 7u, 0x80u);
    dst_p->bms_fault_discharge_enable_relay = unpack_right_shift_u8(src_p[5], 0u, 0x01u);
    dst_p->bms_fault_charger_safety_relay = unpack_right_shift_u8(src_p[5], 1u, 0x02u);
    dst_p->bms_fault_internal_hardware = unpack_right_shift_u8(src_p[5], 2u, 0x04u);
    dst_p->bms_fault_internal_temp = unpack_right_shift_u8(src_p[5], 3u, 0x08u);
    dst_p->bms_fault_internal_logic = unpack_right_shift_u8(src_p[5], 4u, 0x10u);
